import axios from 'axios';
import request from '../Assets/httpload';
import requestlocal from '../Assets/httploadlocal';
import requestnode from '../Assets/httploadnode';
import httploadvideo from '../Assets/httploadvideo';
import { t } from '../i18n';

export default {
  baseURLLocal() {
    return `${window.location.protocol}//${window.location.hostname}:8086/`;
  },
  localApiURL() {
    const isDevelopment = process.env.NODE_ENV === 'development';
    const defaultProdBase = `${window.location.protocol}//${window.location.hostname}:8086/api/local/`;
    return process.env.REACT_APP_LOCAL_API_BASE || (isDevelopment ? '/api/local/' : defaultProdBase);
  },
  mainURL() {
    return `${window.location.protocol}//${window.location.hostname}:8081/`;
  },
  viewURL() {
    return `${window.location.protocol}//${window.location.hostname}:8086/`;
  },
  videoURL() {
    return `${window.location.protocol}//${window.location.hostname}:18080/`;
  },
  getData(url, data) {
    return request({
      url,
      method: 'post',
      data,
    });
  },
  getDataLcoal(url, data) {
    // Local-file APIs are served by in-project Node routes.
    const localNodeEndpoints = new Set(['imgData', 'saveTpl', 'savePage', 'export', 'upload', 'exportImport']);
    if (localNodeEndpoints.has(url)) {
      return requestnode({
        url,
        method: 'post',
        data,
      }).then((res) => {
        if (!res || url !== 'imgData') return res;
        const action = data && data.action;
        if (action !== 'upload' && action !== 'system') return res;
        if (!Array.isArray(res.data)) return res;
        return {
          ...res,
          data: res.data.filter((item) => item && typeof item.imgUrl === 'string' && item.imgUrl.trim() !== ''),
        };
      });
    }

    return requestlocal({
      url,
      method: 'post',
      data,
    });
  },
  getDataVideo(url, data) {
    return httploadvideo({
      url,
      method: 'get',
      data,
    });
  },
  async handlePostSubmit(url, formData) {
    try {
      const result = await axios.post(url, formData, {
        headers: {
          'Content-Type': 'application/x-www-form-urlencoded',
        },
      });
      return result.data;
    } catch (err) {
      console.error(t('http.postError'), err);
      return false;
    }
  },
};
